INSERT INTO collection_items (collection, title, data, visible, sort_order, created_at, updated_at) VALUES ('faq', 'Siparişim ne zaman elime ulaşır?', '{"question": "Siparişim ne zaman elime ulaşır?", "answer": "Siparişler 1-2 iş günü içinde kargoya verilir; teslimat bulunduğunuz yere göre 1-3 gün sürer.", "group": "Kargo"}', 1, 1, NOW(), NOW());
INSERT INTO collection_items (collection, title, data, visible, sort_order, created_at, updated_at) VALUES ('faq', 'Hangi ödeme yöntemlerini kabul ediyorsunuz?', '{"question": "Hangi ödeme yöntemlerini kabul ediyorsunuz?", "answer": "Kredi kartı, banka kartı ve havale/EFT ile ödeme yapabilirsiniz.", "group": "Ödeme"}', 1, 2, NOW(), NOW());
INSERT INTO collection_items (collection, title, data, visible, sort_order, created_at, updated_at) VALUES ('faq', 'İade ve değişim yapabilir miyim?', '{"question": "İade ve değişim yapabilir miyim?", "answer": "Teslimattan itibaren 14 gün içinde, kullanılmamış ürünleri iade edebilir ya da değiştirebilirsiniz.", "group": ""}', 1, 3, NOW(), NOW());
INSERT INTO collection_items (collection, title, data, visible, sort_order, created_at, updated_at) VALUES ('faq', 'Size nasıl ulaşabilirim?', '{"question": "Size nasıl ulaşabilirim?", "answer": "İletişim sayfasındaki formdan, e-postayla ya da telefonla hafta içi 09:00-18:00 arasında bize ulaşabilirsiniz.", "group": ""}', 1, 4, NOW(), NOW());
